@using Tempo.Blazor.Reporting.Services

<TmReportViewer ReportSource="@_source"
                TenantId="tenant-a"
                UserId="user-1"
                Height="760px" />

@code {
    private IReportSource _source = default!;

    protected override void OnInitialized()
    {
        _source = new EmbeddedReportSource(_definition, _dataProvider);
    }
}

@inject HttpClient Http

<TmReportViewer ReportSource="@_source"
                TenantId="tenant-a"
                UserId="user-1"
                CultureName="cs-CZ" />

@code {
    private IReportSource? _source;

    protected override void OnInitialized()
    {
        _source = new RemoteReportSource(Http, "sales-by-region");
    }
}
